import{_ as l,a0 as t,w as o,s as c,ao as d,I as i,x as a,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"如何在 Linux 系統中判斷安裝、使用了多少內存 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 系統中判斷安裝、使用了多少內存 | LCTT (201902) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 系統中判斷安裝、使用了多少內存 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 系統中判斷安裝、使用了多少內存 | LCTT (201902) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201902/20190207 How to determine how much memory is installed, used on Linux systems","title":"如何在 Linux 系統中判斷安裝、使用了多少內存","tag":"201902","desc":""},"relativePath":"201902/20190207 How to determine how much memory is installed, used on Linux systems.md","filePath":"[post].md"}'),r={name:"201902/20190207 How to determine how much memory is installed, used on Linux systems.md"};function h(g,s,k,u,b,f){const n=t("Link");return o(),c("div",null,[s[15]||(s[15]=d(`<h1 id="如何在-linux-系統中判斷安裝、使用了多少內存" tabindex="-1">如何在 Linux 系統中判斷安裝、使用了多少內存 <a class="header-anchor" href="#如何在-linux-系統中判斷安裝、使用了多少內存" aria-label="Permalink to “如何在 Linux 系統中判斷安裝、使用了多少內存”">​</a></h1><blockquote><p>有幾個命令可以報告在 Linux 系統上安裝和使用了多少內存。根據你使用的命令，你可能會被細節淹沒，也可能獲得快速簡單的答案。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/02/memory-100787327-large.jpg" alt=""></p><p>在 Linux 系統中有很多種方法獲取有關安裝了多少內存的信息及查看多少內存正在被使用。有些命令提供了大量的細節，而其他命令提供了簡潔但不一定易於理解的答案。在這篇文章中，我們將介紹一些查看內存及其使用狀態的有用的工具。</p><p>在我們開始之前，讓我們先來回顧一些基礎知識。物理內存和虛擬內存並不是一回事。後者包括配置為交換空間的磁盤空間。交換空間可能包括為此目的特意留出來的分區，以及在創建新的交換分區不可行時創建的用來增加可用交換空間的文件。有些 Linux 命令會提供關於兩者的信息。</p><p>當物理內存佔滿時，交換空間通過提供可以用來存放內存中非活動頁的磁盤空間來擴展內存。</p><p><code>/proc/kcore</code> 是在內存管理中起作用的一個文件。這個文件看上去是個普通文件（雖然非常大），但它並不佔用任何空間。它就像其他 <code>/proc</code> 下的文件一樣是個虛擬文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /proc/kcore</span></span>
<span class="line"><span>-r--------. 1 root root 140737477881856 Jan 28 12:59 /proc/kcore</span></span></code></pre></div><p>有趣的是，下面查詢的兩個系統並沒有安裝相同大小的內存，但 <code>/proc/kcore</code> 的大小卻是相同的。第一個系統安裝了 4 GB 的內存，而第二個系統安裝了 6 GB。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>system1$ ls -l /proc/kcore</span></span>
<span class="line"><span>-r--------. 1 root root 140737477881856 Jan 28 12:59 /proc/kcore</span></span>
<span class="line"><span>system2$ ls -l /proc/kcore</span></span>
<span class="line"><span>-r--------  1 root root 140737477881856 Feb  5 13:00 /proc/kcore</span></span></code></pre></div><p>一種不靠譜的解釋説這個文件代表可用虛擬內存的大小（沒準要加 4 KB），如果這樣，這些系統的虛擬內存可就是 128TB 了！這個數字似乎代表了 64 位系統可以尋址多少內存，而不是當前系統有多少可用內存。在命令列中計算 128 TB 和這個文件大小加上 4 KB 很容易。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ expr 1024 \\* 1024 \\* 1024 \\* 1024 \\* 128</span></span>
<span class="line"><span>140737488355328</span></span>
<span class="line"><span>$ expr 1024 \\* 1024 \\* 1024 \\* 1024 \\* 128 + 4096</span></span>
<span class="line"><span>140737488359424</span></span></code></pre></div><p>另一個用來檢查內存的更人性化的命令是 <code>free</code>。它會給出一個易於理解的內存報告。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:        6102476      812244     4090752       13112     1199480     4984140</span></span>
<span class="line"><span>Swap:       2097148           0     2097148</span></span></code></pre></div><p>使用 <code>-g</code> 選項，<code>free</code> 會以 GB 為單位返回結果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free -g</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:              5           0           3           0           1           4</span></span>
<span class="line"><span>Swap:             1           0           1</span></span></code></pre></div><p>使用 <code>-t</code> 選項，<code>free</code> 會顯示與無附加選項時相同的值（不要把 <code>-t</code> 選項理解成 TB），並額外在輸出的底部添加一行總計數據。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free -t</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:        6102476      812408     4090612       13112     1199456     4983984</span></span>
<span class="line"><span>Swap:       2097148           0     2097148</span></span>
<span class="line"><span>Total:      8199624      812408     6187760</span></span></code></pre></div><p>當然，你也可以選擇同時使用兩個選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free -tg</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:              5           0           3           0           1           4</span></span>
<span class="line"><span>Swap:             1           0           1</span></span>
<span class="line"><span>Total:            7           0           5</span></span></code></pre></div><p>如果你嘗試用這個報告來解釋“這個系統安裝了多少內存？”，你可能會感到失望。上面的報告就是在前文説的裝有 6 GB 內存的系統上運行的結果。這並不是説這個結果是錯的，這就是系統對其可使用的內存的看法。</p><p><code>free</code> 命令也提供了每隔 X 秒刷新顯示的選項（下方示例中 X 為 10）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free -s 10</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:        6102476      812280     4090704       13112     1199492     4984108</span></span>
<span class="line"><span>Swap:       2097148           0     2097148</span></span>
<span class="line"><span></span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:        6102476      812260     4090712       13112     1199504     4984120</span></span>
<span class="line"><span>Swap:       2097148           0     2097148</span></span></code></pre></div><p>使用 <code>-l</code> 選項，<code>free</code> 命令會提供高低內存使用信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free -l</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:        6102476      812376     4090588       13112     1199512     4984000</span></span>
<span class="line"><span>Low:        6102476     2011888     4090588</span></span>
<span class="line"><span>High:             0           0           0</span></span>
<span class="line"><span>Swap:       2097148           0     2097148</span></span></code></pre></div><p>查看內存的另一個選擇是 <code>/proc/meminfo</code> 文件。像 <code>/proc/kcore</code> 一樣，這也是一個虛擬文件，它可以提供關於安裝或使用了多少內存以及可用內存的報告。顯然，空閒內存和可用內存並不是同一回事。<code>MemFree</code> 看起來代表未使用的 RAM。<code>MemAvailable</code> 則是對於啓動新程序時可使用的內存的一個估計。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ head -3 /proc/meminfo</span></span>
<span class="line"><span>MemTotal: 6102476 kB</span></span>
<span class="line"><span>MemFree: 4090596 kB</span></span>
<span class="line"><span>MemAvailable: 4984040 kB</span></span></code></pre></div><p>如果只想查看內存總計，可以使用下面的命令之一：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;/MemTotal/ {print $2}&#39; /proc/meminfo</span></span>
<span class="line"><span>6102476</span></span>
<span class="line"><span>$ grep MemTotal /proc/meminfo</span></span>
<span class="line"><span>MemTotal: 6102476 kB</span></span></code></pre></div><p><code>DirectMap</code> 將內存信息分為幾類。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep DirectMap /proc/meminfo</span></span>
<span class="line"><span>DirectMap4k: 213568 kB</span></span>
<span class="line"><span>DirectMap2M: 6076416 kB</span></span></code></pre></div><p><code>DirectMap4k</code> 代表被映射成標準 4 k 頁的內存大小，<code>DirectMap2M</code> 則顯示了被映射為 2 MB 的頁的內存大小。</p><p><code>getconf</code> 命令將會提供比我們大多數人想要看到的更多的信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ getconf -a | more</span></span>
<span class="line"><span>LINK_MAX 65000</span></span>
<span class="line"><span>_POSIX_LINK_MAX 65000</span></span>
<span class="line"><span>MAX_CANON 255</span></span>
<span class="line"><span>_POSIX_MAX_CANON 255</span></span>
<span class="line"><span>MAX_INPUT 255</span></span>
<span class="line"><span>_POSIX_MAX_INPUT 255</span></span>
<span class="line"><span>NAME_MAX 255</span></span>
<span class="line"><span>_POSIX_NAME_MAX 255</span></span>
<span class="line"><span>PATH_MAX 4096</span></span>
<span class="line"><span>_POSIX_PATH_MAX 4096</span></span>
<span class="line"><span>PIPE_BUF 4096</span></span>
<span class="line"><span>_POSIX_PIPE_BUF 4096</span></span>
<span class="line"><span>SOCK_MAXBUF</span></span>
<span class="line"><span>_POSIX_ASYNC_IO</span></span>
<span class="line"><span>_POSIX_CHOWN_RESTRICTED 1</span></span>
<span class="line"><span>_POSIX_NO_TRUNC 1</span></span>
<span class="line"><span>_POSIX_PRIO_IO</span></span>
<span class="line"><span>_POSIX_SYNC_IO</span></span>
<span class="line"><span>_POSIX_VDISABLE 0</span></span>
<span class="line"><span>ARG_MAX 2097152</span></span>
<span class="line"><span>ATEXIT_MAX 2147483647</span></span>
<span class="line"><span>CHAR_BIT 8</span></span>
<span class="line"><span>CHAR_MAX 127</span></span>
<span class="line"><span>--More--</span></span></code></pre></div><p>使用類似下面的命令來將其輸出精簡為指定的內容，你會得到跟前文提到的其他命令相同的結果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ getconf -a | grep PAGES | awk &#39;BEGIN {total = 1} {if (NR == 1 || NR == 3) total *=$NF} END {print total / 1024&quot; kB&quot;}&#39;</span></span>
<span class="line"><span>6102476 kB</span></span></code></pre></div><p>上面的命令通過將下方輸出的第一行和最後一行的值相乘來計算內存。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PAGESIZE                           4096    &lt;==</span></span>
<span class="line"><span>_AVPHYS_PAGES                      1022511</span></span>
<span class="line"><span>_PHYS_PAGES                        1525619 &lt;==</span></span></code></pre></div><p>自己動手計算一下，我們就知道這個值是怎麼來的了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ expr 4096 \\* 1525619 / 1024</span></span>
<span class="line"><span>6102476</span></span></code></pre></div><p>顯然值得為以上的指令之一設置個 <code>alias</code>。</p><p>另一個具有非常易於理解的輸出的命令是 <code>top</code> 。在 <code>top</code> 輸出的前五行，你可以看到一些數字顯示多少內存正被使用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ top</span></span>
<span class="line"><span>top - 15:36:38 up 8 days, 2:37, 2 users, load average: 0.00, 0.00, 0.00</span></span>
<span class="line"><span>Tasks: 266 total, 1 running, 265 sleeping, 0 stopped, 0 zombie</span></span>
<span class="line"><span>%Cpu(s): 0.2 us, 0.4 sy, 0.0 ni, 99.4 id, 0.0 wa, 0.0 hi, 0.0 si, 0.0 st</span></span>
<span class="line"><span>MiB Mem : 3244.8 total, 377.9 free, 1826.2 used, 1040.7 buff/cache</span></span>
<span class="line"><span>MiB Swap: 3536.0 total, 3535.7 free, 0.3 used. 1126.1 avail Mem</span></span></code></pre></div><p>最後一個命令將會以一個非常簡潔的方式回答“系統安裝了多少內存？”：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dmidecode -t 17 | grep &quot;Size.*MB&quot; | awk &#39;{s+=$2} END {print s / 1024 &quot;GB&quot;}&#39;</span></span>
<span class="line"><span>6GB</span></span></code></pre></div><p>取決於你想要獲取多少細節，Linux 系統提供了許多用來查看系統安裝內存以及使用/空閒內存的選擇。</p><hr>`,47)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3336174/linux/how-much-memory-is-installed-and-being-used-on-your-linux-systems.html"},{default:p(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3336174/linux/how-much-memory-is-installed-and-being-used-on-your-linux-systems.html",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:p(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/leommxj"},{default:p(()=>[...s[4]||(s[4]=[a("leommxj",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const C=l(r,[["render",h]]);export{_ as __pageData,C as default};
